<?php
$edit = null;
$editId = (int) (service('request')->getGet('edit') ?? 0);
if ($editId) {
    foreach ($records as $row) { if ((int) $row['author_id'] === $editId) { $edit = $row; break; } }
}
$e = static fn($value) => esc((string) ($value ?? ''));
?>
