<?php foreach($records as $r): ?><tr><td class="id"><?= (int)$r['author_id'] ?></td><td class="name"><?= $e($r['author_name']) ?></td><td><?= $e($r['department_name'] ?? '—') ?></td><td><?= $e($r['designation_name'] ?? '—') ?></td><td><?= $e($r['subject_name'] ?? '—') ?></td><td>Role ID <?= (int)$r['RollId'] ?></td><td><a class="editlink" href="<?= site_url('master/teachers?edit='.(int)$r['author_id']) ?>">Edit</a></td></tr><?php endforeach; ?>
</tbody></table><?php if(!$records): ?><div class="empty">No teacher records found.</div><?php endif; ?></div></div></section>
</main><script>
const searchBox=document.getElementById('teacherSearch'), rows=[...document.querySelectorAll('#teacherTable tbody tr')], count=document.getElementById('rowCount');
searchBox.addEventListener('input',()=>{const q=searchBox.value.trim().toLocaleLowerCase();let n=0;rows.forEach(row=>{const show=row.innerText.toLocaleLowerCase().includes(q);row.hidden=!show;if(show)n++;});count.textContent=n+' matching record'+(n===1?'':'s');});
const dept=document.getElementById('department_id'), subj=document.getElementById('subject_id');
const subjectDeptMap=Object.fromEntries([...subj.options].filter(o=>o.value).map(o=>[o.value,o.dataset.department]));
function filterSubjects(){const dep=dept.value;[...subj.options].forEach(o=>{if(!o.value)return;const belongs=String(subjectDeptMap[o.value]||'')===String(dep);o.hidden=!!dep&&!belongs;o.disabled=!!dep&&!belongs;});if(subj.selectedOptions.length&&subj.selectedOptions[0].disabled)subj.value='';}
dept.addEventListener('change',filterSubjects);filterSubjects();
</script></body></html>
